'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var cdf = require( './../lib' );


// FIXTURES //

var small = require( './fixtures/python/small_values.json' );
var medium = require( './fixtures/python/medium_values.json' );
var large = require( './fixtures/python/large_values.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof cdf, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the function returns `NaN`', function test( t ) {
	var y;

	y = cdf( NaN, 1.0, 1.0 );
	t.equal( isnan( y ), true, 'returns expected value' );

	y = cdf( 0.0, NaN, 1.0 );
	t.equal( isnan( y ), true, 'returns expected value' );

	y = cdf( 0.0, 1.0, NaN );
	t.equal( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided `c <= 0`, the function returns `NaN`', function test( t ) {
	var y;

	y = cdf( 0.0, 0.0, 1.0 );
	t.equal( isnan( y ), true, 'returns expected value' );

	y = cdf( 0.5, -1.0, 1.0 );
	t.equal( isnan( y ), true, 'returns expected value' );

	y = cdf( 1.0, NINF, 1.0 );
	t.equal( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided `d <= 0`, the function returns `NaN`', function test( t ) {
	var y;

	y = cdf( 0.0, 1.0, 0.0 );
	t.equal( isnan( y ), true, 'returns expected value' );

	y = cdf( 0.5, 1.0, -1.0 );
	t.equal( isnan( y ), true, 'returns expected value' );

	y = cdf( 1.0, 1.0, NINF );
	t.equal( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a number less than or equal to zero for `x` and with finite `c` and finite `d`, the function returns `NaN`', function test( t ) {
	var y;

	y = cdf( NINF, 0.5, 1.0 );
	t.equal( isnan( y ), true, 'returns expected value' );

	y = cdf( -100.0, 0.5, 1.0 );
	t.equal( isnan( y ), true, 'returns expected value' );

	y = cdf( -1.0, 0.5, 1.0 );
	t.equal( isnan( y ), true, 'returns expected value' );

	y = cdf( 0.0, 0.5, 1.0 );
	t.equal( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'the function evaluates the cdf for `x` given small parameters `c` and `d`', function test( t ) {
	var expected;
	var x;
	var c;
	var d;
	var y;
	var i;

	expected = small.expected;
	x = small.x;
	c = small.c;
	d = small.d;
	for ( i = 0; i < x.length; i++ ) {
		y = cdf( x[i], c[i], d[i] );
		if ( y === expected[i] ) {
			t.equal( y, expected[i], 'x: '+x[i]+'. c:'+c[i]+'. d:'+d[i]+', y: '+y+', expected: '+expected[i] );
		} else {
			t.ok( isAlmostSameValue( y, expected[ i ], 3 ), 'within tolerance. x: '+x[ i ]+'. c: '+c[i]+'. d: '+d[i]+'. y: '+y+'. E: '+expected[ i ]+'.' );
		}
	}
	t.end();
});

tape( 'the function evaluates the cdf for `x` given medium parameters `c` and `d`', function test( t ) {
	var expected;
	var x;
	var c;
	var d;
	var y;
	var i;

	expected = medium.expected;
	x = medium.x;
	c = medium.c;
	d = medium.d;
	for ( i = 0; i < x.length; i++ ) {
		y = cdf( x[i], c[i], d[i] );
		if ( y === expected[i] ) {
			t.equal( y, expected[i], 'x: '+x[i]+'. c:'+c[i]+'. d:'+d[i]+', y: '+y+', expected: '+expected[i] );
		} else {
			t.ok( isAlmostSameValue( y, expected[ i ], 8 ), 'within tolerance. x: '+x[ i ]+'. c: '+c[i]+'. d: '+d[i]+'.  y: '+y+'. E: '+expected[ i ]+'.' );
		}
	}
	t.end();
});

tape( 'the function evaluates the cdf for `x` given large parameters `c` and `d`', function test( t ) {
	var expected;
	var x;
	var c;
	var d;
	var y;
	var i;

	expected = large.expected;
	x = large.x;
	c = large.c;
	d = large.d;
	for ( i = 0; i < x.length; i++ ) {
		y = cdf( x[i], c[i], d[i] );
		if ( y === expected[i] ) {
			t.equal( y, expected[i], 'x: '+x[i]+'. c: '+c[i]+'. d: '+d[i]+', y: '+y+', expected: '+expected[i] );
		} else {
			t.ok( isAlmostSameValue( y, expected[ i ], 20 ), 'within tolerance. x: '+x[ i ]+'. c: '+c[i]+'. d: '+d[i]+'. y: '+y+'. E: '+expected[ i ]+'.' );
		}
	}
	t.end();
});
